    'register_md5_before', (SELECT b.src_md5 FROM pg_temp.pb_fn_before b WHERE b.sig = 'public.mcp_register_client(text,text,text,text[],bytea)'::regprocedure::text),
    'refresh_md5_before', (SELECT b.src_md5 FROM pg_temp.pb_fn_before b WHERE b.sig = 'public.mcp_refresh(text,bytea,text,text,bytea,bytea)'::regprocedure::text),
    'attributes_unchanged', (SELECT count(*) = 2 FROM pg_temp.pb_fn_before b JOIN pg_proc p ON p.pronamespace = 'public'::regnamespace AND p.oid::regprocedure::text = b.sig
                             AND p.proacl::text IS NOT DISTINCT FROM b.acl AND p.proconfig IS NOT DISTINCT FROM b.config
                             AND p.prosecdef = b.secdef AND p.proowner = b.owner AND p.provolatile = b.vol AND p.proisstrict = b.strict
                             AND p.proleakproof = b.leakproof AND p.proparallel = b.parallel AND p.procost = b.cost AND p.prorows = b.nrows WHERE b.sig IN ('public.mcp_register_client(text,text,text,text[],bytea)'::regprocedure::text, 'public.mcp_refresh(text,bytea,text,text,bytea,bytea)'::regprocedure::text)),
    'changed', (SELECT coalesce(array_agg(b.sig ORDER BY b.sig COLLATE "C"), '{}') FROM pg_temp.pb_fn_before b
         WHERE EXISTS (SELECT 1 FROM pg_proc p2 WHERE p2.pronamespace = 'public'::regnamespace AND p2.oid::regprocedure::text = b.sig) AND NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.oid::regprocedure::text = b.sig
                             AND p.proacl::text IS NOT DISTINCT FROM b.acl AND p.proconfig IS NOT DISTINCT FROM b.config
                             AND p.prosecdef = b.secdef AND p.proowner = b.owner AND p.provolatile = b.vol AND p.proisstrict = b.strict
                             AND p.proleakproof = b.leakproof AND p.proparallel = b.parallel AND p.procost = b.cost AND p.prorows = b.nrows AND md5(p.prosrc) = b.src_md5)),
    'gone', (SELECT coalesce(array_agg(b.sig ORDER BY b.sig COLLATE "C"), '{}') FROM pg_temp.pb_fn_before b WHERE NOT EXISTS (SELECT 1 FROM pg_proc p2 WHERE p2.pronamespace = 'public'::regnamespace AND p2.oid::regprocedure::text = b.sig)),
    'added', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '{}') FROM pg_proc p
        WHERE p.pronamespace = 'public'::regnamespace AND NOT EXISTS (SELECT 1 FROM pg_temp.pb_fn_before b WHERE b.sig = p.oid::regprocedure::text)),
    'cleanup_shape', (SELECT md5(p.prosrc) = '62843f08da0c36a7214698a9c0476c69' AND p.proowner = 'postgres'::regrole::oid AND p.prosecdef AND p.provolatile = 'v'
          AND NOT p.proisstrict AND p.prolang = (SELECT l.oid FROM pg_language l WHERE l.lanname = 'plpgsql')
          AND array_to_string(p.proconfig, ',') = 'search_path=""' AND p.prorettype = 'integer'::regtype
          AND (SELECT array_agg(DISTINCT a.grantee::regrole::text) FROM aclexplode(p.proacl) a) = ARRAY['postgres']
        FROM pg_proc p WHERE p.oid = to_regprocedure('public._mcp_prune_unused_clients()')),
    'children', (SELECT array_agg(c.relnamespace::regnamespace::text || '.' || c.relname::text || ':' || k.confdeltype::text ORDER BY c.relname::text COLLATE "C")
          FROM pg_constraint k JOIN pg_class c ON c.oid = k.conrelid WHERE k.contype = 'f' AND k.confrelid = 'public.mcp_oauth_clients'::regclass)
        = ARRAY['public.mcp_authorization_requests:c', 'public.mcp_connections:c'],
    'relations_changed', (SELECT count(*) FROM pg_temp.pb_rel_before b WHERE NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relname::text = b.rel AND c.relkind::text = b.kind AND c.relacl::text IS NOT DISTINCT FROM b.acl
                   AND c.relrowsecurity = b.rls AND c.relforcerowsecurity = b.frls AND c.relowner = b.owner
                   AND (SELECT count(*) FROM pg_policy y WHERE y.polrelid = c.oid) = b.npol))
        + (SELECT count(*) FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND NOT EXISTS (SELECT 1 FROM pg_temp.pb_rel_before b WHERE b.rel = c.relname::text)),
    'cron_ours', (SELECT count(*) FROM cron.job j WHERE j.jobname = 'mcp-unused-client-prune') = 1
        AND EXISTS (SELECT 1 FROM cron.job j WHERE j.jobname = 'mcp-unused-client-prune' AND j.schedule = '53 3 * * *' AND j.command = 'SELECT public._mcp_prune_unused_clients()'
                       AND j.username = 'postgres' AND j.active AND j.database = current_database())
        AND (SELECT count(*) FROM cron.job j WHERE j.command ~ '_mcp_prune_unused_clients') = 1,
    'cron_others_changed', (SELECT count(*) FROM pg_temp.pb_cron_snap b WHERE b.jobname IS DISTINCT FROM 'mcp-unused-client-prune' AND NOT EXISTS (SELECT 1 FROM cron.job j WHERE j.jobid = b.jobid
           AND j.jobname IS NOT DISTINCT FROM b.jobname AND j.schedule = b.schedule AND j.command = b.command AND j.username = b.username
           AND j.active = b.active AND j.database = b.database))
        + (SELECT count(*) FROM cron.job j WHERE j.jobname IS DISTINCT FROM 'mcp-unused-client-prune' AND NOT EXISTS (SELECT 1 FROM pg_temp.pb_cron_snap b WHERE b.jobid = j.jobid)),
    'anon_mcp_17', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '{}') FROM pg_proc p
        WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^_?mcp_' AND has_function_privilege('anon', p.oid, 'EXECUTE'))
        = (SELECT array_agg(x ORDER BY x COLLATE "C") FROM unnest(ARRAY['mcp_add_todo(text,bytea,text,text,text,text,text,text)', 'mcp_authorize_begin(text,text,text,text,text,text,text,text,bytea,bytea)', 'mcp_check_access(text,bytea,text)', 'mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'mcp_find_people(text,bytea,text,text,text,text,text,text,text)', 'mcp_get_deal(text,bytea,text,text)', 'mcp_get_deal_checklists(text,bytea,text,text,boolean,text)', 'mcp_get_status(text,bytea,text)', 'mcp_list_all_deals(text,bytea,text,text,text,text,text)', 'mcp_list_deals(text,bytea,text,text,text,integer,text)', 'mcp_list_todos(text,bytea,text,text,text,text,text,boolean,boolean,text)', 'mcp_refresh(text,bytea,text,text,bytea,bytea)', 'mcp_register_client(text,text,text,text[],bytea)', 'mcp_remove_todo(text,bytea,text,text,text)', 'mcp_restore_todo(text,bytea,text,text,text)', 'mcp_update_todo(text,bytea,text,text,jsonb,text)', 'mcp_write_access(text,bytea,text)']::text[]) x),
    'ledger', (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261118190000')) INTO v;
  IF v ->> 'register_md5_before' IS DISTINCT FROM 'ac3e98941cd2f5ef50a16d6409438fb4' THEN w_changed := w_changed || to_jsonb('public.mcp_register_client(text,text,text,text[],bytea)'::regprocedure::text); END IF;
  IF v ->> 'refresh_md5_before' IS DISTINCT FROM '912c6e001271b289c7a8c929492b4ac9' THEN w_changed := w_changed || to_jsonb('public.mcp_refresh(text,bytea,text,text,bytea,bytea)'::regprocedure::text); END IF;
  SELECT coalesce(jsonb_agg(x.s ORDER BY x.s COLLATE "C"), '[]') INTO w_changed FROM jsonb_array_elements_text(w_changed) AS x(s);
  IF v ->> 'register_md5' IS DISTINCT FROM 'ac3e98941cd2f5ef50a16d6409438fb4' OR v ->> 'refresh_md5' IS DISTINCT FROM '912c6e001271b289c7a8c929492b4ac9'
     OR v -> 'changed' IS DISTINCT FROM w_changed OR v -> 'gone' IS DISTINCT FROM '[]'::jsonb
     OR v -> 'added' IS DISTINCT FROM (CASE WHEN EXISTS (SELECT 1 FROM pg_temp.pb_fn_before b WHERE b.sig = 'public._mcp_prune_unused_clients()'::regprocedure::text) THEN '[]'::jsonb ELSE jsonb_build_array('public._mcp_prune_unused_clients()'::regprocedure::text) END)
     OR (v ->> 'attributes_unchanged')::boolean IS NOT TRUE OR (v ->> 'cleanup_shape')::boolean IS NOT TRUE OR (v ->> 'children')::boolean IS NOT TRUE
     OR (v ->> 'relations_changed')::int IS DISTINCT FROM 0 OR (v ->> 'cron_ours')::boolean IS NOT TRUE OR (v ->> 'cron_others_changed')::int IS DISTINCT FROM 0
     OR (v ->> 'anon_mcp_17')::boolean IS NOT TRUE OR (v ->> 'ledger')::int IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'APPLY POST-CHECK 20261118190000 FAILED, nothing applied: %', v;
  END IF;
  RAISE NOTICE 'APPLY POST-CHECK 20261118190000 OK: %', v;
END
$postbounds$;

DO $t1$
BEGIN
  PERFORM pg_temp.rec('t_after_apply', to_jsonb(clock_timestamp()));
  PERFORM pg_temp.rec('lock_timeout_after_apply', to_jsonb(current_setting('lock_timeout')));
  PERFORM pg_temp.rec('cron_jobs_after_apply', to_jsonb((SELECT count(*) FROM cron.job)));
  PERFORM pg_temp.rec('job_run_now_would_delete', to_jsonb((SELECT count(*) FROM public.mcp_oauth_clients k
     WHERE k.created_at < now() - interval '30 days'
       AND NOT EXISTS (SELECT 1 FROM public.mcp_connections c WHERE c.client_id = k.client_id)
       AND NOT EXISTS (SELECT 1 FROM public.mcp_authorization_requests r WHERE r.client_id = k.client_id))));
END $t1$;
-- BACKLOG-4263 PR-10.4 harness: controls, loaded AFTER the migration. Each control is a function returning 'PASS' or
-- 'FAIL: ...'; pg_temp.iso runs one and rolls it back, so controls never see each other's writes.

CREATE FUNCTION pg_temp.iso(fn text) RETURNS text LANGUAGE plpgsql AS $h$
DECLARE x_v text;
BEGIN
  BEGIN
    EXECUTE format('SELECT pg_temp.%I()', fn) INTO x_v;
    RAISE EXCEPTION USING ERRCODE = 'MX001';
  EXCEPTION
    WHEN SQLSTATE 'MX001' THEN NULL;
    WHEN OTHERS THEN x_v := 'FAIL: ERR ' || SQLSTATE || ' ' || left(SQLERRM, 300);
  END;
  RETURN x_v;
END $h$;

CREATE FUNCTION pg_temp.dg(n int) RETURNS bytea LANGUAGE sql IMMUTABLE AS $h$ SELECT decode(substr(pg_temp.dgl(n), 3), 'hex') $h$;
-- the token rows of a connection (compared, never printed)
CREATE FUNCTION pg_temp.tokrows(conn uuid) RETURNS jsonb LANGUAGE sql STABLE AS $h$
  SELECT coalesce(jsonb_agg(jsonb_build_object('h', md5(t.token_sha256::text), 'k', t.kind, 'u', t.used_at, 'e', t.expires_at, 'p', t.pepper_version)
                            ORDER BY t.token_sha256), '[]')
    FROM public.mcp_tokens t WHERE t.connection_id = conn $h$;
CREATE FUNCTION pg_temp.prune() RETURNS integer LANGUAGE sql AS $h$ SELECT public._mcp_prune_unused_clients() $h$;

-- ================================================================ registration
-- 200 a day per address: the day counter set to 199, then the 200th (accepted) and the 201st (refused, counted)
CREATE FUNCTION pg_temp.c_reg_day() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_r jsonb := '{}';
BEGIN
  PERFORM pg_temp.setc('reg_ip_day:' || pg_temp.iph('d1'), '1 day', 199);
  x_r := x_r || jsonb_build_object('call200', pg_temp.w(pg_temp.q_reg('d1a', 'd1')));
  x_r := x_r || jsonb_build_object('call201', pg_temp.w(pg_temp.q_reg('d1b', 'd1')));
  x_r := x_r || jsonb_build_object('other_address', pg_temp.w(pg_temp.q_reg('d2a', 'd2')));
  RETURN pg_temp.all_of(
    pg_temp.pass(x_r -> 'call200' = pg_temp.reg_ok('d1a'), '200th ' || (x_r -> 'call200')::text),
    pg_temp.pass(x_r -> 'call201' = pg_temp.refusal('rate_limited'), '201st ' || (x_r -> 'call201')::text),
    pg_temp.pass(x_r -> 'other_address' = pg_temp.reg_ok('d2a'), 'other address ' || (x_r -> 'other_address')::text),
    pg_temp.pass(pg_temp.cnt('reg_ip_day:' || pg_temp.iph('d1'), '1 day') = 201, 'day count ' || pg_temp.cnt('reg_ip_day:' || pg_temp.iph('d1'), '1 day')),
    pg_temp.pass(pg_temp.rows_of('reg_ip_day:' || pg_temp.iph('d1')) = 1, 'day rows ' || pg_temp.rows_of('reg_ip_day:' || pg_temp.iph('d1'))),
    pg_temp.pass(pg_temp.cnt('reg_ip:' || pg_temp.iph('d1'), '1 hour') = 2, 'hour count ' || pg_temp.cnt('reg_ip:' || pg_temp.iph('d1'), '1 hour')),
    pg_temp.pass(pg_temp.cnt('reg_ip_day:' || pg_temp.iph('d2'), '1 day') = 1, 'other day count ' || pg_temp.cnt('reg_ip_day:' || pg_temp.iph('d2'), '1 day')),
    pg_temp.pass(pg_temp.has_client('d1a') AND NOT pg_temp.has_client('d1b') AND pg_temp.has_client('d2a'), 'registrations'));
END $c$;

-- 60 an hour per address, unchanged: the hour counter set to 59, then the 60th and the 61st
CREATE FUNCTION pg_temp.c_reg_hour() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_r jsonb := '{}';
BEGIN
  PERFORM pg_temp.setc('reg_ip:' || pg_temp.iph('h1'), '1 hour', 59);
  x_r := x_r || jsonb_build_object('call60', pg_temp.w(pg_temp.q_reg('h1a', 'h1')));
  x_r := x_r || jsonb_build_object('call61', pg_temp.w(pg_temp.q_reg('h1b', 'h1')));
  RETURN pg_temp.all_of(
    pg_temp.pass(x_r -> 'call60' = pg_temp.reg_ok('h1a'), '60th ' || (x_r -> 'call60')::text),
    pg_temp.pass(x_r -> 'call61' = pg_temp.refusal('rate_limited'), '61st ' || (x_r -> 'call61')::text),
    pg_temp.pass(pg_temp.cnt('reg_ip:' || pg_temp.iph('h1'), '1 hour') = 61, 'hour count ' || pg_temp.cnt('reg_ip:' || pg_temp.iph('h1'), '1 hour')),
    pg_temp.pass(pg_temp.cnt('reg_ip_day:' || pg_temp.iph('h1'), '1 day') = 1, 'day count ' || pg_temp.cnt('reg_ip_day:' || pg_temp.iph('h1'), '1 day')),
    pg_temp.pass(pg_temp.has_client('h1a') AND NOT pg_temp.has_client('h1b'), 'registrations'));
END $c$;

-- the global daily bound at 5,000: accepted at 600 (above the old 500), the 5,000th accepted, the 5,001st refused
CREATE FUNCTION pg_temp.c_reg_global() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_r jsonb := '{}';
BEGIN
  PERFORM pg_temp.setc('reg_all', '1 day', 600);
  x_r := x_r || jsonb_build_object('at600', pg_temp.w(pg_temp.q_reg('g0a', 'g0')));
  PERFORM pg_temp.setc('reg_all', '1 day', 4999);
  x_r := x_r || jsonb_build_object('call5000', pg_temp.w(pg_temp.q_reg('g1a', 'g1')));
  x_r := x_r || jsonb_build_object('call5001', pg_temp.w(pg_temp.q_reg('g2a', 'g2')));
  RETURN pg_temp.all_of(
    pg_temp.pass(x_r -> 'at600' = pg_temp.reg_ok('g0a'), 'at 600 ' || (x_r -> 'at600')::text),
    pg_temp.pass(x_r -> 'call5000' = pg_temp.reg_ok('g1a'), '5000th ' || (x_r -> 'call5000')::text),
    pg_temp.pass(x_r -> 'call5001' = pg_temp.refusal('rate_limited'), '5001st ' || (x_r -> 'call5001')::text),
    pg_temp.pass(pg_temp.cnt('reg_all', '1 day') = 5001, 'global count ' || pg_temp.cnt('reg_all', '1 day')),
    pg_temp.pass(pg_temp.cnt('reg_ip:' || pg_temp.iph('g2'), '1 hour') = 1 AND pg_temp.cnt('reg_ip_day:' || pg_temp.iph('g2'), '1 day') = 1,
                 'refused address counters'),
    pg_temp.pass(pg_temp.has_client('g1a') AND NOT pg_temp.has_client('g2a'), 'registrations'));
END $c$;

-- a wrong or missing portal secret: refused, no counter row, no log row, no registration
CREATE FUNCTION pg_temp.c_reg_secret() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_all bigint := pg_temp.cnt('reg_all', '1 day'); x_all_rows bigint := pg_temp.rows_of('reg_all');
        x_log bigint := (SELECT count(*) FROM public.mcp_call_log); x_r jsonb := '{}';
BEGIN
  x_r := x_r || jsonb_build_object('wrong', pg_temp.w(pg_temp.q_reg('s1a', 's1', sec_o => 'pb-wrong-secret')));
  x_r := x_r || jsonb_build_object('null', pg_temp.w(pg_temp.q_reg('s1b', 's1', null_secret => true)));
  RETURN pg_temp.all_of(
    pg_temp.pass(x_r = jsonb_build_object('wrong', pg_temp.refusal('invalid_client_metadata'), 'null', pg_temp.refusal('invalid_client_metadata')), 'answers ' || x_r::text),
    pg_temp.pass(pg_temp.rows_of('reg_ip:' || pg_temp.iph('s1')) = 0 AND pg_temp.rows_of('reg_ip_day:' || pg_temp.iph('s1')) = 0,
                 'address counter rows ' || pg_temp.rows_of('reg_ip:' || pg_temp.iph('s1')) || '/' || pg_temp.rows_of('reg_ip_day:' || pg_temp.iph('s1'))),
    pg_temp.pass(pg_temp.cnt('reg_all', '1 day') = x_all AND pg_temp.rows_of('reg_all') = x_all_rows, 'global counter moved'),
    pg_temp.pass((SELECT count(*) FROM public.mcp_call_log) = x_log, 'call log rows added'),
    pg_temp.pass(NOT pg_temp.has_client('s1a') AND NOT pg_temp.has_client('s1b'), 'registered'));
END $c$;

-- ================================================================ refresh
CREATE FUNCTION pg_temp.c_refresh() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_a uuid := pg_temp.id('A'); x_c1 jsonb; x_c2 jsonb; x_k1 uuid; x_k2 uuid; x_b1 text; x_rt int := 1001; x_ok int := 0; x_r jsonb;
        x_inv jsonb := '{}'; x_before jsonb; x_after jsonb; x_61 jsonb; x_61b jsonb; x_tf0 bigint; x_tf1 bigint; x_c60 bigint; x_other jsonb;
        x_later jsonb; x_new_absent boolean; i int;
BEGIN
  x_c1 := pg_temp.connect('rf1', x_a, 'anthropic', 1000, 1001);
  x_c2 := pg_temp.connect('rf2', x_a, 'openai', 2000, 2001);
  x_k1 := pg_temp.id('conn:rf1'); x_k2 := pg_temp.id('conn:rf2');
  x_b1 := 'refresh_conn:' || x_k1::text;
  -- refused attempts that present connection 1's live refresh token: not counted in refresh_conn
  x_inv := x_inv || jsonb_build_object('wrong_client', pg_temp.w(pg_temp.q_rf(1001, 1100, 1101, client_o => pg_temp.cid('other'))));
  x_inv := x_inv || jsonb_build_object('wrong_resource', pg_temp.w(pg_temp.q_rf(1001, 1102, 1103, res_o => 'https://pb-other.example.test/api/mcp')));
  x_inv := x_inv || jsonb_build_object('wrong_secret', pg_temp.w(pg_temp.q_rf(1001, 1104, 1105, sec_o => 'pb-wrong-secret')));
  x_inv := x_inv || jsonb_build_object('unknown_token', pg_temp.w(pg_temp.q_rf(1999, 1106, 1107)));
  x_inv := x_inv || jsonb_build_object('rows_after_invalid', pg_temp.rows_of(x_b1));
  -- 60 refreshes of connection 1 in this hour, each presenting the refresh token the previous one issued
  FOR i IN 1..60 LOOP
    x_r := pg_temp.w(pg_temp.q_rf(x_rt, 3000 + 2 * i, 3001 + 2 * i));
    IF x_r = pg_temp.ok_answer() THEN x_ok := x_ok + 1; x_rt := 3001 + 2 * i; END IF;
  END LOOP;
  x_before := pg_temp.tokrows(x_k1);
  x_tf0 := pg_temp.cnt('tok_fail:' || pg_temp.client(), '1 minute');
  x_61 := pg_temp.w(pg_temp.q_rf(x_rt, 5000, 5001));
  x_after := pg_temp.tokrows(x_k1);
  x_new_absent := NOT EXISTS (SELECT 1 FROM public.mcp_tokens t WHERE t.token_sha256 IN (sha256(pg_temp.dg(5000)), sha256(pg_temp.dg(5001))));
  x_61b := pg_temp.w(pg_temp.q_rf(x_rt, 5002, 5003));
  x_tf1 := pg_temp.cnt('tok_fail:' || pg_temp.client(), '1 minute');
  x_c60 := pg_temp.cnt(x_b1, '1 hour');
  x_other := pg_temp.w(pg_temp.q_rf(2001, 2100, 2101));
  -- the hour passes (the counter row moved one window back), then the refused refresh token is presented again
  UPDATE public.mcp_rate_counters SET window_start = window_start - interval '1 hour' WHERE bucket = x_b1;
  x_later := pg_temp.w(pg_temp.q_rf(x_rt, 5004, 5005));
  RETURN pg_temp.all_of(
    pg_temp.pass(x_c1 ->> 'consent' = 'approve' AND x_c1 -> 'exchange' = pg_temp.ok_answer() AND (x_c1 ->> 'conn')::boolean
                 AND x_c2 ->> 'consent' = 'approve' AND x_c2 -> 'exchange' = pg_temp.ok_answer() AND (x_c2 ->> 'conn')::boolean,
                 'connect ' || x_c1::text || ' ' || x_c2::text),
    pg_temp.pass(x_inv = jsonb_build_object('wrong_client', pg_temp.refusal('invalid_grant'), 'wrong_resource', pg_temp.refusal('invalid_grant'),
                                            'wrong_secret', pg_temp.refusal('invalid_grant'), 'unknown_token', pg_temp.refusal('invalid_grant'),
                                            'rows_after_invalid', 0), 'refused attempts ' || x_inv::text),
    pg_temp.pass(x_ok = 60, 'accepted in the hour ' || x_ok),
    pg_temp.pass(x_61 = pg_temp.refusal('rate_limited'), '61st ' || x_61::text),
    pg_temp.pass(x_after = x_before, 'the refused refresh changed connection 1''s token rows: ' || jsonb_array_length(x_before) || ' -> ' || jsonb_array_length(x_after)
                 || ', used ' || (SELECT count(*) FROM jsonb_array_elements(x_after) e WHERE e ->> 'u' IS NOT NULL)),
    pg_temp.pass(x_new_absent, 'a token was stored for the refused refresh'),
    pg_temp.pass(x_61b = pg_temp.refusal('rate_limited'), 'again ' || x_61b::text),
    pg_temp.pass(x_tf1 = x_tf0, 'tok_fail count moved'),
    pg_temp.pass(x_c60 = 60, 'refresh_conn count ' || x_c60),
    pg_temp.pass(x_other = pg_temp.ok_answer(), 'other connection of the same user ' || x_other::text),
    pg_temp.pass(x_later = pg_temp.ok_answer(), 'after the hour, the same refresh token ' || x_later::text),
    pg_temp.pass(EXISTS (SELECT 1 FROM public.mcp_connections c WHERE c.id = x_k1 AND c.status = 'active'), 'connection 1 gone'),
    pg_temp.pass(NOT EXISTS (SELECT 1 FROM public.mcp_call_log l WHERE l.user_id = x_a AND l.event = 'refresh_reuse'), 'refresh_reuse logged'),
    pg_temp.pass(pg_temp.cnt(x_b1, '1 hour') = 1 AND pg_temp.cnt('refresh_conn:' || x_k2::text, '1 hour') = 1,
                 'counts after the hour ' || pg_temp.cnt(x_b1, '1 hour') || '/' || pg_temp.cnt('refresh_conn:' || x_k2::text, '1 hour')));
END $c$;

-- ================================================================ cleanup
CREATE FUNCTION pg_temp.c_prune_rule() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_empty integer; x_n integer; x_keep jsonb; x_kids bigint;
BEGIN
  x_empty := pg_temp.prune();
  PERFORM pg_temp.pclient('p31', '31 days');
  PERFORM pg_temp.pclient('p29', '29 days');
  PERFORM pg_temp.pclient('pact', '31 days'); PERFORM pg_temp.pconn('pact', 'active');
  PERFORM pg_temp.pclient('ppend', '31 days'); PERFORM pg_temp.pconn('ppend', 'pending');
  PERFORM pg_temp.pclient('rqp', '31 days'); PERFORM pg_temp.preq('rqp', 'pending', false);
  PERFORM pg_temp.pclient('rqa', '31 days'); PERFORM pg_temp.preq('rqa', 'approved', false);
  PERFORM pg_temp.pclient('rqd', '31 days'); PERFORM pg_temp.preq('rqd', 'denied', false);
  PERFORM pg_temp.pclient('rqx', '31 days'); PERFORM pg_temp.preq('rqx', 'pending', true);
  x_n := pg_temp.prune();
  SELECT jsonb_object_agg(k, pg_temp.has_client(k)) INTO x_keep FROM unnest(ARRAY['p31', 'p29', 'pact', 'ppend', 'rqp', 'rqa', 'rqd', 'rqx']) k;
  SELECT (SELECT count(*) FROM public.mcp_connections c WHERE c.client_id IN (pg_temp.cid('pact'), pg_temp.cid('ppend')))
       + (SELECT count(*) FROM public.mcp_authorization_requests r WHERE r.client_id IN (pg_temp.cid('rqp'), pg_temp.cid('rqa'), pg_temp.cid('rqd'), pg_temp.cid('rqx')))
    INTO x_kids;
  RETURN pg_temp.all_of(
    pg_temp.pass(x_empty = 0, 'nothing to delete answered ' || coalesce(x_empty::text, 'null')),
    pg_temp.pass(x_n = 1, 'deleted ' || coalesce(x_n::text, 'null')),
    pg_temp.pass(x_keep = '{"p31": false, "p29": true, "pact": true, "ppend": true, "rqp": true, "rqa": true, "rqd": true, "rqx": true}'::jsonb, 'kept ' || x_keep::text),
    pg_temp.pass(x_kids = 6, 'child rows ' || x_kids),
    pg_temp.pass(pg_temp.real_changed() = 0, 'pre-existing registrations changed or locked: ' || pg_temp.real_changed()),
    pg_temp.pass(pg_temp.real_selectable() = 0, 'pre-existing registrations selectable: ' || pg_temp.real_selectable()));
END $c$;

-- at most 500 per run: 501 eligible registrations take two runs
CREATE FUNCTION pg_temp.c_prune_cap() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_1 integer; x_2 integer; x_3 integer;
BEGIN
  INSERT INTO public.mcp_oauth_clients (client_id, client_name, redirect_uris, ip_sha256, created_at)
  SELECT pg_temp.cid('cap' || n), 'Fixture app cap', ARRAY[pg_temp.redir('anthropic')], pg_temp.ipd('cap'), now() - interval '40 days' - n * interval '1 second'
    FROM generate_series(1, 501) n;
  x_1 := pg_temp.prune(); x_2 := pg_temp.prune(); x_3 := pg_temp.prune();
  RETURN pg_temp.all_of(
    pg_temp.pass(x_1 = 500 AND x_2 = 1 AND x_3 = 0, 'runs ' || coalesce(x_1::text, 'null') || ', ' || coalesce(x_2::text, 'null') || ', ' || coalesce(x_3::text, 'null')),
    pg_temp.pass(NOT EXISTS (SELECT 1 FROM public.mcp_oauth_clients c WHERE c.client_name = 'Fixture app cap'), 'left over'),
    pg_temp.pass(pg_temp.real_changed() = 0, 'pre-existing registrations changed or locked: ' || pg_temp.real_changed()));
END $c$;

-- the check repeated after the lock: an authorization request appears for a selected registration while the run is
-- in progress (an AFTER DELETE trigger on the registration deleted just before it) -> that registration is kept
CREATE FUNCTION pg_temp.trg_child_appears() RETURNS trigger LANGUAGE plpgsql AS $t$
BEGIN
  IF OLD.client_id = pg_temp.cid('rcA') THEN
    PERFORM pg_temp.preq('rcB', 'pending', false);
  END IF;
  RETURN OLD;
END $t$;
CREATE FUNCTION pg_temp.c_prune_recheck() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_n integer;
BEGIN
  PERFORM pg_temp.pclient('rcA', '32 days');
  PERFORM pg_temp.pclient('rcB', '31 days');
  EXECUTE 'CREATE TRIGGER x4263_child_appears AFTER DELETE ON public.mcp_oauth_clients FOR EACH ROW EXECUTE FUNCTION pg_temp.trg_child_appears()';
  x_n := pg_temp.prune();
  RETURN pg_temp.all_of(
    pg_temp.pass(x_n = 1, 'deleted ' || coalesce(x_n::text, 'null')),
    pg_temp.pass(NOT pg_temp.has_client('rcA'), 'first registration kept'),
    pg_temp.pass(pg_temp.has_client('rcB'), 'the registration whose request appeared was deleted'),
    pg_temp.pass((SELECT count(*) FROM public.mcp_authorization_requests r WHERE r.client_id = pg_temp.cid('rcB')) = 1, 'the request is gone'));
END $c$;

-- a third table with a foreign key to mcp_oauth_clients: the run deletes nothing
CREATE FUNCTION pg_temp.c_prune_other_child() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_n integer;
BEGIN
  PERFORM pg_temp.pclient('oc1', '31 days');
  PERFORM pg_temp.pclient('oc2', '31 days');
  EXECUTE 'CREATE TABLE public.x4263_child (client_id text NOT NULL REFERENCES public.mcp_oauth_clients (client_id) ON DELETE CASCADE)';
  EXECUTE format('INSERT INTO public.x4263_child (client_id) VALUES (%L)', pg_temp.cid('oc2'));
  x_n := pg_temp.prune();
  RETURN pg_temp.all_of(
    pg_temp.pass(x_n = 0, 'deleted ' || coalesce(x_n::text, 'null')),
    pg_temp.pass(pg_temp.has_client('oc1') AND pg_temp.has_client('oc2'), 'kept ' || pg_temp.has_client('oc1') || '/' || pg_temp.has_client('oc2')));
END $c$;

-- no API role may execute the cleanup; its attributes
CREATE FUNCTION pg_temp.c_prune_grants() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_anon jsonb; x_auth text; x_svc text; x_attr boolean;
BEGIN
  PERFORM pg_temp.pclient('gr1', '31 days');
  x_anon := pg_temp.w('SELECT to_jsonb(public._mcp_prune_unused_clients())');
  x_auth := pg_temp.call_as(pg_temp.id('A'), 'SELECT to_jsonb(public._mcp_prune_unused_clients())', 'authenticated');
  x_svc := pg_temp.call_as(NULL, 'SELECT to_jsonb(public._mcp_prune_unused_clients())', 'service_role');
  SELECT p.prosecdef AND p.provolatile = 'v' AND p.proowner = 'postgres'::regrole::oid AND array_to_string(p.proconfig, ',') = 'search_path=""'
         AND p.prolang = (SELECT l.oid FROM pg_language l WHERE l.lanname = 'plpgsql')
         AND (SELECT array_agg(DISTINCT a.grantee::regrole::text) FROM aclexplode(p.proacl) a) = ARRAY['postgres']
         AND NOT has_function_privilege('anon', p.oid, 'EXECUTE') AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE')
         AND NOT has_function_privilege('service_role', p.oid, 'EXECUTE')
    INTO x_attr FROM pg_proc p WHERE p.oid = to_regprocedure('public._mcp_prune_unused_clients()');
  RETURN pg_temp.all_of(
    pg_temp.pass(x_anon ->> 'sqlerr' = '42501', 'anon ' || x_anon::text),
    pg_temp.pass(x_auth LIKE 'ERR 42501%', 'authenticated ' || x_auth),
    pg_temp.pass(x_svc LIKE 'ERR 42501%', 'service_role ' || x_svc),
    pg_temp.pass(x_attr, 'attributes or grants'),
    pg_temp.pass(pg_temp.has_client('gr1'), 'a refused caller deleted a registration'));
END $c$;

-- the tables with a foreign key to mcp_oauth_clients (pg_temp.children, in fixtures.sql): exactly the two the cleanup checks
CREATE FUNCTION pg_temp.c_children() RETURNS text LANGUAGE sql STABLE AS $c$
  SELECT pg_temp.pass(pg_temp.children() = '["public.mcp_authorization_requests:c", "public.mcp_connections:c"]'::jsonb, 'children ' || pg_temp.children()::text)
$c$;

-- the cron job: once, this schedule and command, active, as postgres in this database; the other jobs unchanged
CREATE FUNCTION pg_temp.c_cron() RETURNS text LANGUAGE plpgsql AS $c$
BEGIN
  RETURN pg_temp.all_of(
    pg_temp.pass((SELECT count(*) FROM cron.job j WHERE j.jobname = 'mcp-unused-client-prune') = 1, 'jobs named ' || (SELECT count(*) FROM cron.job j WHERE j.jobname = 'mcp-unused-client-prune')),
    pg_temp.pass(EXISTS (SELECT 1 FROM cron.job j WHERE j.jobname = 'mcp-unused-client-prune' AND j.schedule = '53 3 * * *'
                           AND j.command = 'SELECT public._mcp_prune_unused_clients()' AND j.username = 'postgres' AND j.active
                           AND j.database = current_database()), 'job shape'),
    pg_temp.pass((SELECT count(*) FROM cron.job j WHERE j.command ~ '_mcp_prune_unused_clients') = 1, 'jobs running the cleanup ' || (SELECT count(*) FROM cron.job j WHERE j.command ~ '_mcp_prune_unused_clients')),
    pg_temp.pass((SELECT count(*) FROM cron.job j WHERE j.jobname IS DISTINCT FROM 'mcp-unused-client-prune')
                 = (SELECT (v #>> '{}')::bigint FROM pg_temp.pb_out WHERE k = 'fx_cron_jobs_before'), 'other jobs'),
    pg_temp.pass(NOT EXISTS (SELECT 1 FROM pg_temp.pb_cron_before b WHERE NOT EXISTS (
                   SELECT 1 FROM cron.job j WHERE j.jobid = b.jobid AND j.jobname IS NOT DISTINCT FROM b.jobname AND j.schedule = b.schedule
                      AND j.command = b.command AND j.username = b.username AND j.active = b.active)), 'an existing job changed'));
END $c$;

-- ---------------------------------------------------------------- catalogue: the apply post-check, run again
CREATE FUNCTION pg_temp.c_catalog() RETURNS text LANGUAGE plpgsql AS $h$
BEGIN
  EXECUTE $pcq$DO $postbounds$
DECLARE v jsonb; w_changed jsonb := '[]';
BEGIN
  SELECT jsonb_build_object(
    'register_md5', (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.mcp_register_client(text,text,text,text[],bytea)'::regprocedure),
    'refresh_md5', (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.mcp_refresh(text,bytea,text,text,bytea,bytea)'::regprocedure),
    'register_md5_before', (SELECT b.src_md5 FROM pg_temp.pb_fn_before b WHERE b.sig = 'public.mcp_register_client(text,text,text,text[],bytea)'::regprocedure::text),
    'refresh_md5_before', (SELECT b.src_md5 FROM pg_temp.pb_fn_before b WHERE b.sig = 'public.mcp_refresh(text,bytea,text,text,bytea,bytea)'::regprocedure::text),
    'attributes_unchanged', (SELECT count(*) = 2 FROM pg_temp.pb_fn_before b JOIN pg_proc p ON p.pronamespace = 'public'::regnamespace AND p.oid::regprocedure::text = b.sig
                             AND p.proacl::text IS NOT DISTINCT FROM b.acl AND p.proconfig IS NOT DISTINCT FROM b.config
                             AND p.prosecdef = b.secdef AND p.proowner = b.owner AND p.provolatile = b.vol AND p.proisstrict = b.strict
                             AND p.proleakproof = b.leakproof AND p.proparallel = b.parallel AND p.procost = b.cost AND p.prorows = b.nrows WHERE b.sig IN ('public.mcp_register_client(text,text,text,text[],bytea)'::regprocedure::text, 'public.mcp_refresh(text,bytea,text,text,bytea,bytea)'::regprocedure::text)),
    'changed', (SELECT coalesce(array_agg(b.sig ORDER BY b.sig COLLATE "C"), '{}') FROM pg_temp.pb_fn_before b
         WHERE EXISTS (SELECT 1 FROM pg_proc p2 WHERE p2.pronamespace = 'public'::regnamespace AND p2.oid::regprocedure::text = b.sig) AND NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.oid::regprocedure::text = b.sig
                             AND p.proacl::text IS NOT DISTINCT FROM b.acl AND p.proconfig IS NOT DISTINCT FROM b.config
                             AND p.prosecdef = b.secdef AND p.proowner = b.owner AND p.provolatile = b.vol AND p.proisstrict = b.strict
                             AND p.proleakproof = b.leakproof AND p.proparallel = b.parallel AND p.procost = b.cost AND p.prorows = b.nrows AND md5(p.prosrc) = b.src_md5)),
    'gone', (SELECT coalesce(array_agg(b.sig ORDER BY b.sig COLLATE "C"), '{}') FROM pg_temp.pb_fn_before b WHERE NOT EXISTS (SELECT 1 FROM pg_proc p2 WHERE p2.pronamespace = 'public'::regnamespace AND p2.oid::regprocedure::text = b.sig)),
    'added', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '{}') FROM pg_proc p
        WHERE p.pronamespace = 'public'::regnamespace AND NOT EXISTS (SELECT 1 FROM pg_temp.pb_fn_before b WHERE b.sig = p.oid::regprocedure::text)),
    'cleanup_shape', (SELECT md5(p.prosrc) = '62843f08da0c36a7214698a9c0476c69' AND p.proowner = 'postgres'::regrole::oid AND p.prosecdef AND p.provolatile = 'v'
          AND NOT p.proisstrict AND p.prolang = (SELECT l.oid FROM pg_language l WHERE l.lanname = 'plpgsql')
          AND array_to_string(p.proconfig, ',') = 'search_path=""' AND p.prorettype = 'integer'::regtype
          AND (SELECT array_agg(DISTINCT a.grantee::regrole::text) FROM aclexplode(p.proacl) a) = ARRAY['postgres']
        FROM pg_proc p WHERE p.oid = to_regprocedure('public._mcp_prune_unused_clients()')),
    'children', (SELECT array_agg(c.relnamespace::regnamespace::text || '.' || c.relname::text || ':' || k.confdeltype::text ORDER BY c.relname::text COLLATE "C")
          FROM pg_constraint k JOIN pg_class c ON c.oid = k.conrelid WHERE k.contype = 'f' AND k.confrelid = 'public.mcp_oauth_clients'::regclass)
        = ARRAY['public.mcp_authorization_requests:c', 'public.mcp_connections:c'],
    'relations_changed', (SELECT count(*) FROM pg_temp.pb_rel_before b WHERE NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relname::text = b.rel AND c.relkind::text = b.kind AND c.relacl::text IS NOT DISTINCT FROM b.acl
                   AND c.relrowsecurity = b.rls AND c.relforcerowsecurity = b.frls AND c.relowner = b.owner
                   AND (SELECT count(*) FROM pg_policy y WHERE y.polrelid = c.oid) = b.npol))
        + (SELECT count(*) FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND NOT EXISTS (SELECT 1 FROM pg_temp.pb_rel_before b WHERE b.rel = c.relname::text)),
    'cron_ours', (SELECT count(*) FROM cron.job j WHERE j.jobname = 'mcp-unused-client-prune') = 1
        AND EXISTS (SELECT 1 FROM cron.job j WHERE j.jobname = 'mcp-unused-client-prune' AND j.schedule = '53 3 * * *' AND j.command = 'SELECT public._mcp_prune_unused_clients()'
                       AND j.username = 'postgres' AND j.active AND j.database = current_database())
        AND (SELECT count(*) FROM cron.job j WHERE j.command ~ '_mcp_prune_unused_clients') = 1,
    'cron_others_changed', (SELECT count(*) FROM pg_temp.pb_cron_snap b WHERE b.jobname IS DISTINCT FROM 'mcp-unused-client-prune' AND NOT EXISTS (SELECT 1 FROM cron.job j WHERE j.jobid = b.jobid
           AND j.jobname IS NOT DISTINCT FROM b.jobname AND j.schedule = b.schedule AND j.command = b.command AND j.username = b.username
           AND j.active = b.active AND j.database = b.database))
        + (SELECT count(*) FROM cron.job j WHERE j.jobname IS DISTINCT FROM 'mcp-unused-client-prune' AND NOT EXISTS (SELECT 1 FROM pg_temp.pb_cron_snap b WHERE b.jobid = j.jobid)),
    'anon_mcp_17', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '{}') FROM pg_proc p
        WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^_?mcp_' AND has_function_privilege('anon', p.oid, 'EXECUTE'))
        = (SELECT array_agg(x ORDER BY x COLLATE "C") FROM unnest(ARRAY['mcp_add_todo(text,bytea,text,text,text,text,text,text)', 'mcp_authorize_begin(text,text,text,text,text,text,text,text,bytea,bytea)', 'mcp_check_access(text,bytea,text)', 'mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'mcp_find_people(text,bytea,text,text,text,text,text,text,text)', 'mcp_get_deal(text,bytea,text,text)', 'mcp_get_deal_checklists(text,bytea,text,text,boolean,text)', 'mcp_get_status(text,bytea,text)', 'mcp_list_all_deals(text,bytea,text,text,text,text,text)', 'mcp_list_deals(text,bytea,text,text,text,integer,text)', 'mcp_list_todos(text,bytea,text,text,text,text,text,boolean,boolean,text)', 'mcp_refresh(text,bytea,text,text,bytea,bytea)', 'mcp_register_client(text,text,text,text[],bytea)', 'mcp_remove_todo(text,bytea,text,text,text)', 'mcp_restore_todo(text,bytea,text,text,text)', 'mcp_update_todo(text,bytea,text,text,jsonb,text)', 'mcp_write_access(text,bytea,text)']::text[]) x),
    'ledger', (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261118190000')) INTO v;
  IF v ->> 'register_md5_before' IS DISTINCT FROM 'ac3e98941cd2f5ef50a16d6409438fb4' THEN w_changed := w_changed || to_jsonb('public.mcp_register_client(text,text,text,text[],bytea)'::regprocedure::text); END IF;
  IF v ->> 'refresh_md5_before' IS DISTINCT FROM '912c6e001271b289c7a8c929492b4ac9' THEN w_changed := w_changed || to_jsonb('public.mcp_refresh(text,bytea,text,text,bytea,bytea)'::regprocedure::text); END IF;
  SELECT coalesce(jsonb_agg(x.s ORDER BY x.s COLLATE "C"), '[]') INTO w_changed FROM jsonb_array_elements_text(w_changed) AS x(s);
  IF v ->> 'register_md5' IS DISTINCT FROM 'ac3e98941cd2f5ef50a16d6409438fb4' OR v ->> 'refresh_md5' IS DISTINCT FROM '912c6e001271b289c7a8c929492b4ac9'
     OR v -> 'changed' IS DISTINCT FROM w_changed OR v -> 'gone' IS DISTINCT FROM '[]'::jsonb
     OR v -> 'added' IS DISTINCT FROM (CASE WHEN EXISTS (SELECT 1 FROM pg_temp.pb_fn_before b WHERE b.sig = 'public._mcp_prune_unused_clients()'::regprocedure::text) THEN '[]'::jsonb ELSE jsonb_build_array('public._mcp_prune_unused_clients()'::regprocedure::text) END)
     OR (v ->> 'attributes_unchanged')::boolean IS NOT TRUE OR (v ->> 'cleanup_shape')::boolean IS NOT TRUE OR (v ->> 'children')::boolean IS NOT TRUE
     OR (v ->> 'relations_changed')::int IS DISTINCT FROM 0 OR (v ->> 'cron_ours')::boolean IS NOT TRUE OR (v ->> 'cron_others_changed')::int IS DISTINCT FROM 0
     OR (v ->> 'anon_mcp_17')::boolean IS NOT TRUE OR (v ->> 'ledger')::int IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'APPLY POST-CHECK 20261118190000 FAILED, nothing applied: %', v;
  END IF;
  RAISE NOTICE 'APPLY POST-CHECK 20261118190000 OK: %', v;
END
$postbounds$;
$pcq$;
  RETURN 'PASS';
EXCEPTION WHEN OTHERS THEN RETURN 'FAIL: ' || left(SQLERRM, 900);
END $h$;

-- ---------------------------------------------------------------- the migration's own post-check, run again
CREATE FUNCTION pg_temp.c_mig_post() RETURNS text LANGUAGE plpgsql AS $h$
BEGIN
  EXECUTE $mpq$DO $post4263bounds$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object(
    'register', (SELECT md5(p.prosrc) = 'ac3e98941cd2f5ef50a16d6409438fb4' AND p.prosecdef AND array_to_string(p.proconfig, ',') = 'search_path=""'
                        AND has_function_privilege('anon', p.oid, 'EXECUTE') AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE')
                        AND NOT has_function_privilege('service_role', p.oid, 'EXECUTE')
                   FROM pg_catalog.pg_proc p WHERE p.oid = 'public.mcp_register_client(text,text,text,text[],bytea)'::regprocedure),
    'refresh', (SELECT md5(p.prosrc) = '912c6e001271b289c7a8c929492b4ac9' AND p.prosecdef AND array_to_string(p.proconfig, ',') = 'search_path=""'
                       AND has_function_privilege('anon', p.oid, 'EXECUTE') AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE')
                       AND NOT has_function_privilege('service_role', p.oid, 'EXECUTE')
                  FROM pg_catalog.pg_proc p WHERE p.oid = 'public.mcp_refresh(text,bytea,text,text,bytea,bytea)'::regprocedure),
    'prune', (SELECT md5(p.prosrc) = '62843f08da0c36a7214698a9c0476c69' AND p.prosecdef AND p.provolatile = 'v' AND p.proowner = 'postgres'::regrole::oid
                     AND array_to_string(p.proconfig, ',') = 'search_path=""'
                     AND (SELECT array_agg(DISTINCT a.grantee::regrole::text) FROM aclexplode(p.proacl) a) = ARRAY['postgres']
                FROM pg_catalog.pg_proc p WHERE p.oid = 'public._mcp_prune_unused_clients()'::regprocedure),
    'children', (SELECT array_agg(c.relnamespace::regnamespace::text || '.' || c.relname::text ORDER BY c.relname::text COLLATE "C")
                   FROM pg_catalog.pg_constraint k JOIN pg_catalog.pg_class c ON c.oid = k.conrelid
                  WHERE k.contype = 'f' AND k.confrelid = 'public.mcp_oauth_clients'::regclass)
                = ARRAY['public.mcp_authorization_requests', 'public.mcp_connections'],
    'cron', (SELECT count(*) FROM cron.job j WHERE j.jobname = 'mcp-unused-client-prune') = 1
            AND EXISTS (SELECT 1 FROM cron.job j WHERE j.jobname = 'mcp-unused-client-prune' AND j.schedule = '53 3 * * *'
                           AND j.command = 'SELECT public._mcp_prune_unused_clients()' AND j.username = 'postgres' AND j.active
                           AND j.database = current_database()),
    'anon_mcp', (SELECT coalesce(array_agg(x.sig ORDER BY x.sig COLLATE "C"), '{}')
                   FROM (SELECT p.proname::text || '(' || replace(pg_catalog.oidvectortypes(p.proargtypes), ', ', ',') || ')' AS sig
                           FROM pg_catalog.pg_proc p
                          WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^_?mcp_' AND has_function_privilege('anon', p.oid, 'EXECUTE')) x)
                = ARRAY['mcp_add_todo(text,bytea,text,text,text,text,text,text)',
                 'mcp_authorize_begin(text,text,text,text,text,text,text,text,bytea,bytea)',
                 'mcp_check_access(text,bytea,text)',
                 'mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)',
                 'mcp_find_people(text,bytea,text,text,text,text,text,text,text)',
                 'mcp_get_deal(text,bytea,text,text)',
                 'mcp_get_deal_checklists(text,bytea,text,text,boolean,text)',
                 'mcp_get_status(text,bytea,text)',
                 'mcp_list_all_deals(text,bytea,text,text,text,text,text)',
                 'mcp_list_deals(text,bytea,text,text,text,integer,text)',
                 'mcp_list_todos(text,bytea,text,text,text,text,text,boolean,boolean,text)',
                 'mcp_refresh(text,bytea,text,text,bytea,bytea)',
                 'mcp_register_client(text,text,text,text[],bytea)',
                 'mcp_remove_todo(text,bytea,text,text,text)',
                 'mcp_restore_todo(text,bytea,text,text,text)',
                 'mcp_update_todo(text,bytea,text,text,jsonb,text)',
                 'mcp_write_access(text,bytea,text)']::text[]) INTO v;
  IF (v ->> 'register')::boolean IS NOT TRUE OR (v ->> 'refresh')::boolean IS NOT TRUE OR (v ->> 'prune')::boolean IS NOT TRUE
     OR (v ->> 'children')::boolean IS NOT TRUE OR (v ->> 'cron')::boolean IS NOT TRUE OR (v ->> 'anon_mcp')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'BACKLOG-4263: bounds post-check failed: %', v;
  END IF;
END
$post4263bounds$;$mpq$;
  RETURN 'PASS';
EXCEPTION WHEN OTHERS THEN RETURN 'FAIL: ' || left(SQLERRM, 900);
END $h$;

-- ================================================================ the bodies before this migration, under temporary names
-- registration: one case, set up, call fn as anon; answer and side effects (reg_ip_day excluded); rolled back
CREATE FUNCTION pg_temp.eq_reg_case(cs text, fn text) RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_k text := 'eq-' || cs; x_out text; x_r jsonb; x_all0 bigint;
BEGIN
  BEGIN
    PERFORM pg_temp.setc('reg_all', '1 day', 10);
    x_all0 := pg_temp.cnt('reg_all', '1 day');
    IF cs = 'disabled' THEN UPDATE public.mcp_settings SET enabled = false WHERE id; END IF;
    IF cs = 'ip_hour_limited' THEN PERFORM pg_temp.setc('reg_ip:' || pg_temp.iph('eq'), '1 hour', 60); END IF;
    IF cs = 'reg_all_400' THEN PERFORM pg_temp.setc('reg_all', '1 day', 400); x_all0 := 400; END IF;
    IF cs = 'duplicate' THEN PERFORM pg_temp.w(pg_temp.q_reg(x_k, 'eq', fn)); END IF;
    x_r := pg_temp.w(CASE cs
      WHEN 'wrong_secret' THEN pg_temp.q_reg(x_k, 'eq', fn, sec_o => 'pb-wrong-secret')
      WHEN 'null_secret' THEN pg_temp.q_reg(x_k, 'eq', fn, null_secret => true)
      WHEN 'bad_ip' THEN pg_temp.q_reg(x_k, 'eq', fn, ip_o => '\x0102')
      WHEN 'bad_client_id' THEN pg_temp.q_reg(x_k, 'eq', fn, cid_o => 'kpr_c_short')
      WHEN 'bad_name' THEN pg_temp.q_reg(x_k, 'eq', fn, name_o => '')
      WHEN 'bad_redirect' THEN pg_temp.q_reg(x_k, 'eq', fn, redir_o => ARRAY['https://pb-fixture.example.test/cb'])
      ELSE pg_temp.q_reg(x_k, 'eq', fn) END);
    x_out := jsonb_build_object('res', x_r, 'fx', jsonb_build_object(
      'registered', pg_temp.has_client(x_k),
      'reg_ip', pg_temp.cnt('reg_ip:' || pg_temp.iph('eq'), '1 hour'),
      'reg_all_delta', pg_temp.cnt('reg_all', '1 day') - x_all0,
      'log', (SELECT count(*) FROM public.mcp_call_log l WHERE l.ended_at = now())))::text;
    RAISE EXCEPTION USING ERRCODE = 'MX004';
  EXCEPTION WHEN SQLSTATE 'MX004' THEN NULL;
  END;
  RETURN x_out;
END $c$;
CREATE FUNCTION pg_temp.eq_reg_cases() RETURNS text[] LANGUAGE sql IMMUTABLE AS $h$
  SELECT ARRAY['ok', 'wrong_secret', 'null_secret', 'disabled', 'bad_ip', 'bad_client_id', 'bad_name', 'bad_redirect', 'duplicate',
               'ip_hour_limited', 'reg_all_400'] $h$;
-- refresh: one case on a fresh connection of user A; answer and side effects (refresh_conn excluded); rolled back
CREATE FUNCTION pg_temp.effects_rf(u uuid) RETURNS jsonb LANGUAGE sql STABLE AS $h$
  SELECT jsonb_build_object(
    'conns', (SELECT coalesce(jsonb_agg(c.status || ' ' || c.provider ORDER BY c.status, c.provider), '[]') FROM public.mcp_connections c WHERE c.user_id = u),
    'tokens', (SELECT count(*) FROM public.mcp_tokens t JOIN public.mcp_connections c ON c.id = t.connection_id WHERE c.user_id = u),
    'tokens_used', (SELECT count(*) FROM public.mcp_tokens t JOIN public.mcp_connections c ON c.id = t.connection_id WHERE c.user_id = u AND t.used_at IS NOT NULL),
    'log', (SELECT coalesce(jsonb_agg(l.event || ' ' || l.outcome ORDER BY l.event, l.outcome), '[]') FROM public.mcp_call_log l WHERE l.user_id = u),
    'tok_fail', jsonb_build_array(pg_temp.rows_of('tok_fail:' || pg_temp.client()), pg_temp.cnt('tok_fail:' || pg_temp.client(), '1 minute'),
                                  pg_temp.cnt('tok_fail:' || pg_temp.cid('other'), '1 minute'), pg_temp.rows_of('tok_fail:' || pg_temp.cid('nobody'))))
$h$;
CREATE FUNCTION pg_temp.eq_rf_case(cs text, fn text) RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_u uuid := pg_temp.id('A'); x_k text := 'eqr-' || cs; x_out text; x_r jsonb;
BEGIN
  BEGIN
    PERFORM pg_temp.connect(x_k, x_u, 'anthropic', 7000, 7001);
    IF cs = 'expired' THEN
      UPDATE public.mcp_tokens SET issued_at = now() - interval '2 hours', expires_at = now() - interval '1 second' WHERE token_sha256 = sha256(pg_temp.dg(7001));
    END IF;
    IF cs = 'reuse' THEN PERFORM pg_temp.w(pg_temp.q_rf(7001, 7102, 7103, fn)); END IF;
    x_r := pg_temp.w(CASE cs
      WHEN 'wrong_secret' THEN pg_temp.q_rf(7001, 7100, 7101, fn, sec_o => 'pb-wrong-secret')
      WHEN 'null_secret' THEN pg_temp.q_rf(7001, 7100, 7101, fn, null_secret => true)
      WHEN 'bad_length' THEN format('SELECT public.%I(%L, %L::bytea, %L, %L, %L::bytea, %L::bytea)', fn, pg_temp.secret(), pg_temp.dgl(7001),
                                    pg_temp.client(), pg_temp.res(), '\x0102', pg_temp.dgl(7101))
      WHEN 'same_digests' THEN pg_temp.q_rf(7001, 7100, 7100, fn)
      WHEN 'wrong_client' THEN pg_temp.q_rf(7001, 7100, 7101, fn, client_o => pg_temp.cid('other'))
      WHEN 'unknown_client' THEN pg_temp.q_rf(7001, 7100, 7101, fn, client_o => pg_temp.cid('nobody'))
      WHEN 'wrong_resource' THEN pg_temp.q_rf(7001, 7100, 7101, fn, res_o => 'https://pb-other.example.test/api/mcp')
      WHEN 'unknown_token' THEN pg_temp.q_rf(7999, 7100, 7101, fn)
      WHEN 'token_clash' THEN pg_temp.q_rf(7001, 7000, 7101, fn)
      ELSE pg_temp.q_rf(7001, 7100, 7101, fn) END);
    x_out := jsonb_build_object('res', x_r, 'fx', pg_temp.effects_rf(x_u))::text;
    RAISE EXCEPTION USING ERRCODE = 'MX004';
  EXCEPTION WHEN SQLSTATE 'MX004' THEN NULL;
  END;
  RETURN x_out;
END $c$;
CREATE FUNCTION pg_temp.eq_rf_cases() RETURNS text[] LANGUAGE sql IMMUTABLE AS $h$
  SELECT ARRAY['ok', 'wrong_secret', 'null_secret', 'bad_length', 'same_digests', 'wrong_client', 'unknown_client', 'wrong_resource', 'unknown_token',
               'expired', 'reuse', 'token_clash'] $h$;
CREATE FUNCTION pg_temp.c_equal() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_cs text; x_o text; x_n text; x_bad text := ''; x_seen text[] := '{}'; x_seen_r text[] := '{}';
BEGIN
  FOREACH x_cs IN ARRAY pg_temp.eq_reg_cases() LOOP
    x_o := pg_temp.eq_reg_case(x_cs, 'mcp_register_client_x4263old');
    x_n := pg_temp.eq_reg_case(x_cs, 'mcp_register_client');
    IF x_o IS DISTINCT FROM x_n THEN
      x_bad := x_bad || 'register ' || x_cs || ': old ' || left(coalesce(x_o, 'null'), 250) || ' new ' || left(coalesce(x_n, 'null'), 250) || '; ';
    END IF;
    x_seen_r := x_seen_r || coalesce((x_n::jsonb -> 'res')::text, 'null');
  END LOOP;
  FOREACH x_cs IN ARRAY pg_temp.eq_rf_cases() LOOP
    x_o := pg_temp.eq_rf_case(x_cs, 'mcp_refresh_x4263old');
    x_n := pg_temp.eq_rf_case(x_cs, 'mcp_refresh');
    IF x_o IS DISTINCT FROM x_n THEN
      x_bad := x_bad || 'refresh ' || x_cs || ': old ' || left(coalesce(x_o, 'null'), 250) || ' new ' || left(coalesce(x_n, 'null'), 250) || '; ';
    END IF;
    x_seen := x_seen || coalesce((x_n::jsonb -> 'res')::text, 'null');
  END LOOP;
  RETURN pg_temp.all_of(
    pg_temp.pass(x_bad = '', x_bad),
    pg_temp.pass((SELECT count(DISTINCT s) FROM unnest(x_seen_r) s) >= 4, 'register answers do not differ: ' || array_to_string(x_seen_r, ' ')),
    pg_temp.pass((SELECT count(DISTINCT s) FROM unnest(x_seen) s) >= 3, 'refresh answers do not differ: ' || array_to_string(x_seen, ' ')));
END $c$;
CREATE FUNCTION pg_temp.eq_report() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE x_cs text; x_out jsonb := '{}';
BEGIN
  FOREACH x_cs IN ARRAY pg_temp.eq_reg_cases() LOOP
    x_out := x_out || jsonb_build_object('register_' || x_cs, pg_temp.eq_reg_case(x_cs, 'mcp_register_client')::jsonb);
  END LOOP;
  FOREACH x_cs IN ARRAY pg_temp.eq_rf_cases() LOOP
    x_out := x_out || jsonb_build_object('refresh_' || x_cs, pg_temp.eq_rf_case(x_cs, 'mcp_refresh')::jsonb);
  END LOOP;
  RETURN x_out::text;
END $c$;
CREATE FUNCTION pg_temp.with_old(fn text) RETURNS text LANGUAGE plpgsql AS $h$
DECLARE x_v text; x_ok boolean := false;
BEGIN
  BEGIN
    EXECUTE $orq$CREATE FUNCTION public.mcp_register_client_x4263old(p_secret text, p_client_id text, p_client_name text, p_redirect_uris text[], p_ip_sha256 bytea)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_b text;
BEGIN
  IF public._mcp_secret_ok(p_secret) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_client_metadata');
  END IF;
  IF (SELECT s.enabled FROM public.mcp_settings s WHERE s.id) IS NOT TRUE THEN
    RETURN public._mcp_refuse('busy');
  END IF;
  IF (octet_length(p_ip_sha256) = 32) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_client_metadata');
  END IF;
  IF (p_client_id ~ '^kpr_c_[A-Za-z0-9_-]{22}$'
      AND char_length(p_client_name) BETWEEN 1 AND 100) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_client_metadata');
  END IF;
  IF (cardinality(p_redirect_uris) BETWEEN 1 AND 3
      AND array_position(p_redirect_uris, NULL) IS NULL
      AND NOT EXISTS (SELECT 1 FROM unnest(p_redirect_uris) u(uri)
                       WHERE NOT EXISTS (SELECT 1 FROM public.mcp_redirect_allowlist a WHERE a.redirect_uri = u.uri))) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_redirect_uri');
  END IF;
  v_b := public._mcp_bump('reg_ip:' || encode(p_ip_sha256, 'hex'), interval '1 hour', 60);
  IF v_b IS NOT DISTINCT FROM 'ok' THEN
    v_b := public._mcp_bump('reg_all', interval '1 day', 500);
  END IF;
  IF v_b IS DISTINCT FROM 'ok' THEN
    RETURN public._mcp_refuse(coalesce(v_b, 'busy'));
  END IF;
  INSERT INTO public.mcp_oauth_clients (client_id, client_name, redirect_uris, ip_sha256)
  VALUES (p_client_id, p_client_name, p_redirect_uris, p_ip_sha256)
  ON CONFLICT (client_id) DO NOTHING;
  IF NOT FOUND THEN
    RETURN public._mcp_refuse('invalid_client_metadata');
  END IF;
  RETURN jsonb_build_object('ok', true, 'client_id', p_client_id, 'client_name', p_client_name,
                            'redirect_uris', to_jsonb(p_redirect_uris));
END
$fn$;$orq$;
    EXECUTE $ofq$CREATE FUNCTION public.mcp_refresh_x4263old(p_secret text, p_rt_digest bytea, p_client_id text, p_resource text, p_new_at_digest bytea, p_new_rt_digest bytea)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_conn   uuid;
  v_user   uuid;
  v_pepper smallint;
  v_scope  text;
BEGIN
  /*BODY:4263-5*/
  IF public._mcp_secret_ok(p_secret) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_grant');
  END IF;
  IF (octet_length(p_rt_digest) = 32 AND octet_length(p_new_at_digest) = 32 AND octet_length(p_new_rt_digest) = 32
      AND p_new_at_digest IS DISTINCT FROM p_new_rt_digest) IS NOT TRUE THEN
    RETURN public._mcp_token_fail(p_client_id, 'invalid_request');
  END IF;

  -- token insert failure: everything in this block is rolled back (the presented token stays unused)
  BEGIN
  UPDATE public.mcp_tokens t
     SET used_at = now()
    FROM public.mcp_connections c, public.mcp_settings s
   WHERE t.token_sha256 = sha256(p_rt_digest)
     AND t.kind = 'refresh'
     AND t.used_at IS NULL
     AND t.expires_at > now()
     AND s.id
     AND t.pepper_version = s.pepper_version
     AND c.id = t.connection_id
     AND c.status = 'active'
     AND c.client_id = p_client_id
     AND c.resource = p_resource
  RETURNING t.connection_id, c.user_id, s.pepper_version, c.scope INTO v_conn, v_user, v_pepper, v_scope;

  IF v_conn IS NULL THEN
    SELECT t.connection_id, c.user_id INTO v_conn, v_user
      FROM public.mcp_tokens t
      JOIN public.mcp_connections c ON c.id = t.connection_id
     WHERE t.token_sha256 = sha256(p_rt_digest)
       AND t.kind = 'refresh'
       AND t.used_at IS NOT NULL;
    IF v_conn IS NOT NULL THEN
      DELETE FROM public.mcp_connections c WHERE c.id = v_conn;
      INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at) VALUES (v_user, v_conn, 'refresh_reuse', 'ok', now());
    END IF;
    RETURN public._mcp_token_fail(p_client_id, 'invalid_grant');
  END IF;

  BEGIN
    INSERT INTO public.mcp_tokens (token_sha256, connection_id, kind, pepper_version, expires_at) VALUES
      (sha256(p_new_at_digest), v_conn, 'access', v_pepper, now() + interval '1 hour'),
      (sha256(p_new_rt_digest), v_conn, 'refresh', v_pepper, now() + interval '30 days');
  EXCEPTION WHEN unique_violation OR not_null_violation THEN
    RAISE EXCEPTION USING ERRCODE = 'MC001', MESSAGE = 'mcp token insert failed';
  END;
  DELETE FROM public.mcp_tokens o
   WHERE o.connection_id = v_conn AND o.expires_at < now() - interval '1 day';
  RETURN jsonb_build_object('ok', true, 'token_type', 'Bearer', 'expires_in', 3600, 'scope', v_scope);   /*SCOPE:refresh*/
  EXCEPTION WHEN SQLSTATE 'MC001' THEN
    RETURN public._mcp_token_fail(p_client_id, 'invalid_request');
  END;
END
$fn$;$ofq$;
    EXECUTE 'GRANT EXECUTE ON FUNCTION public.mcp_register_client_x4263old(text, text, text, text[], bytea) TO anon';
    EXECUTE 'GRANT EXECUTE ON FUNCTION public.mcp_refresh_x4263old(text, bytea, text, text, bytea, bytea) TO anon';
    SELECT bool_and(p.prosecdef) AND count(*) = 2
           AND bool_or(md5(p.prosrc) = '27326378a7ca849f4a116f6b46e1767e' AND p.proname = 'mcp_register_client_x4263old')
           AND bool_or(md5(p.prosrc) = 'a7797a967b1952dec493c48c62328530' AND p.proname = 'mcp_refresh_x4263old') INTO x_ok
      FROM pg_proc p WHERE p.oid IN (to_regprocedure('public.mcp_register_client_x4263old(text,text,text,text[],bytea)'),
                                     to_regprocedure('public.mcp_refresh_x4263old(text,bytea,text,text,bytea,bytea)'));
    EXECUTE format('SELECT pg_temp.%I()', fn) INTO x_v;
    RAISE EXCEPTION USING ERRCODE = 'MX003';
  EXCEPTION WHEN SQLSTATE 'MX003' THEN NULL;
    WHEN OTHERS THEN x_v := 'FAIL: ERR ' || SQLSTATE || ' ' || left(SQLERRM, 300);
  END;
  IF x_ok IS NOT TRUE THEN
    RETURN 'FAIL: the old copies are not installed at md5 27326378a7ca849f4a116f6b46e1767e / a7797a967b1952dec493c48c62328530 (' || coalesce(x_v, '') || ')';
  END IF;
  RETURN x_v;
END $h$;

-- ================================================================ re-run of the migration
DO $rerun$
BEGIN
  EXECUTE $migq$-- ============================================================================
-- Migration: bounds on AI-app registration and token refresh, and a daily cleanup of unused app registrations
-- (BACKLOG-4263 PR-10.4)
--
-- Replaced (pre-check below), both anon, portal secret still checked first, grants restated:
--   mcp_register_client: the hourly bound per hashed address (reg_ip, 60) is unchanged; a daily bound per hashed
--     address is added (reg_ip_day, 200, checked after reg_ip); the global daily bound (reg_all) is raised from 500 to
--     5,000. Same counter helper, same refusal. The body is otherwise character-identical to 20261112170000.
--   mcp_refresh: at most 60 refreshes per connection per hour (refresh_conn:<connection id>), counted only when the
--     presented refresh token is valid. Over the bound the answer is {"ok":false,"error":"rate_limited"}, no token is
--     issued and the presented refresh token stays unused. Every other answer is unchanged. The body is otherwise
--     character-identical to 20261118130000.
-- New: _mcp_prune_unused_clients(), SECURITY DEFINER, owner postgres, no API role may execute it, run daily by pg_cron
--   (job mcp-unused-client-prune, 03:53 UTC, as postgres). It deletes an mcp_oauth_clients row only when the row was
--   created more than 30 days ago and no mcp_connections row (any status) and no mcp_authorization_requests row (any
--   status) names it; at most 500 per run; each candidate is locked FOR UPDATE SKIP LOCKED and the conditions are
--   checked again in a separate statement before the delete. It deletes nothing when any other table has a foreign key
--   to mcp_oauth_clients. Answers the number deleted.
-- Existing rows: none changed by this file.
-- Requires: the pg_cron extension (created by 20261118110000); otherwise nothing is applied.
-- Locks: lock_timeout 3s before the first replaced function; if a lock is not obtained within 3 seconds the migration
--   fails and nothing is applied.
-- Pre-check: mcp_register_client is at md5 27326378a7ca849f4a116f6b46e1767e (20261112170000) or ac3e98941cd2f5ef50a16d6409438fb4 (this file);
--   mcp_refresh is at md5 a7797a967b1952dec493c48c62328530 (20261118130000) or 912c6e001271b289c7a8c929492b4ac9 (this file); otherwise nothing is applied.
-- Re-runnable: CREATE OR REPLACE; cron.schedule by name replaces the job.
-- Rollback: supabase/tests/backlog-4263-bounds/rollback-20261118190000.sql (run it before any rollback of
--   20261118130000 or 20261112170000).
-- ============================================================================

DO $pre4263bounds$
DECLARE v_r text; v_f text;
BEGIN
  SELECT md5(p.prosrc) INTO v_r FROM pg_catalog.pg_proc p WHERE p.oid = to_regprocedure('public.mcp_register_client(text,text,text,text[],bytea)');
  SELECT md5(p.prosrc) INTO v_f FROM pg_catalog.pg_proc p WHERE p.oid = to_regprocedure('public.mcp_refresh(text,bytea,text,text,bytea,bytea)');
  IF v_r IS NULL OR v_r NOT IN ('27326378a7ca849f4a116f6b46e1767e', 'ac3e98941cd2f5ef50a16d6409438fb4') THEN
    RAISE EXCEPTION 'BACKLOG-4263: public.mcp_register_client is not at the expected body (md5 %)', coalesce(v_r, 'missing');
  END IF;
  IF v_f IS NULL OR v_f NOT IN ('a7797a967b1952dec493c48c62328530', '912c6e001271b289c7a8c929492b4ac9') THEN
    RAISE EXCEPTION 'BACKLOG-4263: public.mcp_refresh is not at the expected body (md5 %)', coalesce(v_f, 'missing');
  END IF;
  IF to_regclass('cron.job') IS NULL THEN
    RAISE EXCEPTION 'BACKLOG-4263: pg_cron is not installed';
  END IF;
END
$pre4263bounds$;

SET LOCAL lock_timeout = '3s';

-- ============================================================================ registration (anon)
-- Order: secret, enabled, arguments, redirect allow-list, then the counters: a refused request
-- adds to no counter. 4263 PR-10.4: reg_ip_day added, reg_all raised to 5,000.
-- Intentionally callable by anon: OAuth dynamic client registration
CREATE OR REPLACE FUNCTION public.mcp_register_client(p_secret text, p_client_id text, p_client_name text, p_redirect_uris text[], p_ip_sha256 bytea)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_b text;
BEGIN
  /*BODY:4263-10.4-register*/
  IF public._mcp_secret_ok(p_secret) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_client_metadata');
  END IF;
  IF (SELECT s.enabled FROM public.mcp_settings s WHERE s.id) IS NOT TRUE THEN
    RETURN public._mcp_refuse('busy');
  END IF;
  IF (octet_length(p_ip_sha256) = 32) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_client_metadata');
  END IF;
  IF (p_client_id ~ '^kpr_c_[A-Za-z0-9_-]{22}$'
      AND char_length(p_client_name) BETWEEN 1 AND 100) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_client_metadata');
  END IF;
  IF (cardinality(p_redirect_uris) BETWEEN 1 AND 3
      AND array_position(p_redirect_uris, NULL) IS NULL
      AND NOT EXISTS (SELECT 1 FROM unnest(p_redirect_uris) u(uri)
                       WHERE NOT EXISTS (SELECT 1 FROM public.mcp_redirect_allowlist a WHERE a.redirect_uri = u.uri))) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_redirect_uri');
  END IF;
  v_b := public._mcp_bump('reg_ip:' || encode(p_ip_sha256, 'hex'), interval '1 hour', 60);
  IF v_b IS NOT DISTINCT FROM 'ok' THEN
    v_b := public._mcp_bump('reg_ip_day:' || encode(p_ip_sha256, 'hex'), interval '1 day', 200);   /*BOUND:reg_ip_day*/
  END IF;
  IF v_b IS NOT DISTINCT FROM 'ok' THEN
    v_b := public._mcp_bump('reg_all', interval '1 day', 5000);   /*BOUND:reg_all*/
  END IF;
  IF v_b IS DISTINCT FROM 'ok' THEN
    RETURN public._mcp_refuse(coalesce(v_b, 'busy'));
  END IF;
  INSERT INTO public.mcp_oauth_clients (client_id, client_name, redirect_uris, ip_sha256)
  VALUES (p_client_id, p_client_name, p_redirect_uris, p_ip_sha256)
  ON CONFLICT (client_id) DO NOTHING;
  IF NOT FOUND THEN
    RETURN public._mcp_refuse('invalid_client_metadata');
  END IF;
  RETURN jsonb_build_object('ok', true, 'client_id', p_client_id, 'client_name', p_client_name,
                            'redirect_uris', to_jsonb(p_redirect_uris));
END
$fn$;
REVOKE ALL ON FUNCTION public.mcp_register_client(text, text, text, text[], bytea) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.mcp_register_client(text, text, text, text[], bytea) TO anon;

-- ============================================================================ refresh (anon)
-- 4263 PR-5: answers the connection's scope; a refresh never changes it. 4263 PR-10.4: refresh_conn bound.
-- Intentionally callable by anon: OAuth refresh token grant for a registered client (portal secret checked inside)
CREATE OR REPLACE FUNCTION public.mcp_refresh(p_secret text, p_rt_digest bytea, p_client_id text, p_resource text, p_new_at_digest bytea, p_new_rt_digest bytea)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_conn   uuid;
  v_user   uuid;
  v_pepper smallint;
  v_scope  text;
BEGIN
  /*BODY:4263-10.4-refresh*/
  IF public._mcp_secret_ok(p_secret) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_grant');
  END IF;
  IF (octet_length(p_rt_digest) = 32 AND octet_length(p_new_at_digest) = 32 AND octet_length(p_new_rt_digest) = 32
      AND p_new_at_digest IS DISTINCT FROM p_new_rt_digest) IS NOT TRUE THEN
    RETURN public._mcp_token_fail(p_client_id, 'invalid_request');
  END IF;

  -- token insert failure: everything in this block is rolled back (the presented token stays unused)
  BEGIN
  UPDATE public.mcp_tokens t
     SET used_at = now()
    FROM public.mcp_connections c, public.mcp_settings s
   WHERE t.token_sha256 = sha256(p_rt_digest)
     AND t.kind = 'refresh'
     AND t.used_at IS NULL
     AND t.expires_at > now()
     AND s.id
     AND t.pepper_version = s.pepper_version
     AND c.id = t.connection_id
     AND c.status = 'active'
     AND c.client_id = p_client_id
     AND c.resource = p_resource
  RETURNING t.connection_id, c.user_id, s.pepper_version, c.scope INTO v_conn, v_user, v_pepper, v_scope;

  IF v_conn IS NULL THEN
    SELECT t.connection_id, c.user_id INTO v_conn, v_user
      FROM public.mcp_tokens t
      JOIN public.mcp_connections c ON c.id = t.connection_id
     WHERE t.token_sha256 = sha256(p_rt_digest)
       AND t.kind = 'refresh'
       AND t.used_at IS NOT NULL;
    IF v_conn IS NOT NULL THEN
      DELETE FROM public.mcp_connections c WHERE c.id = v_conn;
      INSERT INTO public.mcp_call_log (user_id, connection_id, event, outcome, ended_at) VALUES (v_user, v_conn, 'refresh_reuse', 'ok', now());
    END IF;
    RETURN public._mcp_token_fail(p_client_id, 'invalid_grant');
  END IF;

  -- 4263 PR-10.4: at most 60 refreshes per connection per hour. Over the bound this block is rolled back: no token
  -- is issued and the presented refresh token stays unused.
  IF public._mcp_bump('refresh_conn:' || v_conn::text, interval '1 hour', 60) IS DISTINCT FROM 'ok' THEN   /*BOUND:refresh_conn*/
    RAISE EXCEPTION USING ERRCODE = 'MC003', MESSAGE = 'mcp refresh bound reached';
  END IF;

  BEGIN
    INSERT INTO public.mcp_tokens (token_sha256, connection_id, kind, pepper_version, expires_at) VALUES
      (sha256(p_new_at_digest), v_conn, 'access', v_pepper, now() + interval '1 hour'),
      (sha256(p_new_rt_digest), v_conn, 'refresh', v_pepper, now() + interval '30 days');
  EXCEPTION WHEN unique_violation OR not_null_violation THEN
    RAISE EXCEPTION USING ERRCODE = 'MC001', MESSAGE = 'mcp token insert failed';
  END;
  DELETE FROM public.mcp_tokens o
   WHERE o.connection_id = v_conn AND o.expires_at < now() - interval '1 day';
  RETURN jsonb_build_object('ok', true, 'token_type', 'Bearer', 'expires_in', 3600, 'scope', v_scope);   /*SCOPE:refresh*/
  EXCEPTION WHEN SQLSTATE 'MC001' THEN
    RETURN public._mcp_token_fail(p_client_id, 'invalid_request');
  WHEN SQLSTATE 'MC003' THEN
    RETURN public._mcp_refuse('rate_limited');   /*REFUSE:refresh_conn*/
  END;
END
$fn$;
REVOKE ALL ON FUNCTION public.mcp_refresh(text, bytea, text, text, bytea, bytea) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.mcp_refresh(text, bytea, text, text, bytea, bytea) TO anon;

-- ============================================================================ cleanup (pg_cron only)
CREATE OR REPLACE FUNCTION public._mcp_prune_unused_clients()
RETURNS integer LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_id   text;
  v_lock text;
  v_d    integer;
  v_n    integer := 0;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_constraint k
              WHERE k.contype = 'f' AND k.confrelid = 'public.mcp_oauth_clients'::regclass
                AND k.conrelid NOT IN ('public.mcp_connections'::regclass, 'public.mcp_authorization_requests'::regclass)) THEN   /*GUARD:children*/
    RETURN 0;
  END IF;
  FOR v_id IN
    SELECT k.client_id FROM public.mcp_oauth_clients k
     WHERE k.created_at < now() - interval '30 days'   /*AGE:select*/
       AND NOT EXISTS (SELECT 1 FROM public.mcp_connections c WHERE c.client_id = k.client_id)   /*SELECT:connections*/
       AND NOT EXISTS (SELECT 1 FROM public.mcp_authorization_requests r WHERE r.client_id = k.client_id)   /*SELECT:requests*/
     ORDER BY k.created_at, k.client_id
     LIMIT 500   /*CAP:run*/
  LOOP
    v_lock := NULL;
    SELECT k.client_id INTO v_lock FROM public.mcp_oauth_clients k
     WHERE k.client_id = v_id
       FOR UPDATE SKIP LOCKED;   /*LOCK:client*/
    CONTINUE WHEN v_lock IS NULL;
    DELETE FROM public.mcp_oauth_clients k
     WHERE k.client_id = v_lock
       AND k.created_at < now() - interval '30 days'   /*AGE:recheck*/
       AND NOT EXISTS (SELECT 1 FROM public.mcp_connections c WHERE c.client_id = k.client_id)   /*RECHECK:connections*/
       AND NOT EXISTS (SELECT 1 FROM public.mcp_authorization_requests r WHERE r.client_id = k.client_id);   /*RECHECK:requests*/
    GET DIAGNOSTICS v_d = ROW_COUNT;
    v_n := v_n + v_d;
  END LOOP;
  RETURN v_n;
END
$fn$;
REVOKE ALL ON FUNCTION public._mcp_prune_unused_clients() FROM PUBLIC, anon, authenticated, service_role;

-- Daily at 03:53 UTC, as the database owner. Stop: SELECT cron.unschedule('mcp-unused-client-prune');
DO $cron4263bounds$
BEGIN
  PERFORM cron.schedule('mcp-unused-client-prune', '53 3 * * *', 'SELECT public._mcp_prune_unused_clients()');
END
$cron4263bounds$;

-- Post-check: bodies, attributes and grants of the three functions; the tables with a foreign key to
-- mcp_oauth_clients are exactly the two the cleanup checks; the anon-callable mcp functions are exactly the 17 named;
-- the cron job exists once with this schedule and command, active, as postgres.
DO $post4263bounds$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object(
    'register', (SELECT md5(p.prosrc) = 'ac3e98941cd2f5ef50a16d6409438fb4' AND p.prosecdef AND array_to_string(p.proconfig, ',') = 'search_path=""'
                        AND has_function_privilege('anon', p.oid, 'EXECUTE') AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE')
                        AND NOT has_function_privilege('service_role', p.oid, 'EXECUTE')
                   FROM pg_catalog.pg_proc p WHERE p.oid = 'public.mcp_register_client(text,text,text,text[],bytea)'::regprocedure),
    'refresh', (SELECT md5(p.prosrc) = '912c6e001271b289c7a8c929492b4ac9' AND p.prosecdef AND array_to_string(p.proconfig, ',') = 'search_path=""'
                       AND has_function_privilege('anon', p.oid, 'EXECUTE') AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE')
                       AND NOT has_function_privilege('service_role', p.oid, 'EXECUTE')
                  FROM pg_catalog.pg_proc p WHERE p.oid = 'public.mcp_refresh(text,bytea,text,text,bytea,bytea)'::regprocedure),
    'prune', (SELECT md5(p.prosrc) = '62843f08da0c36a7214698a9c0476c69' AND p.prosecdef AND p.provolatile = 'v' AND p.proowner = 'postgres'::regrole::oid
                     AND array_to_string(p.proconfig, ',') = 'search_path=""'
                     AND (SELECT array_agg(DISTINCT a.grantee::regrole::text) FROM aclexplode(p.proacl) a) = ARRAY['postgres']
                FROM pg_catalog.pg_proc p WHERE p.oid = 'public._mcp_prune_unused_clients()'::regprocedure),
    'children', (SELECT array_agg(c.relnamespace::regnamespace::text || '.' || c.relname::text ORDER BY c.relname::text COLLATE "C")
                   FROM pg_catalog.pg_constraint k JOIN pg_catalog.pg_class c ON c.oid = k.conrelid
                  WHERE k.contype = 'f' AND k.confrelid = 'public.mcp_oauth_clients'::regclass)
                = ARRAY['public.mcp_authorization_requests', 'public.mcp_connections'],
    'cron', (SELECT count(*) FROM cron.job j WHERE j.jobname = 'mcp-unused-client-prune') = 1
            AND EXISTS (SELECT 1 FROM cron.job j WHERE j.jobname = 'mcp-unused-client-prune' AND j.schedule = '53 3 * * *'
                           AND j.command = 'SELECT public._mcp_prune_unused_clients()' AND j.username = 'postgres' AND j.active
                           AND j.database = current_database()),
    'anon_mcp', (SELECT coalesce(array_agg(x.sig ORDER BY x.sig COLLATE "C"), '{}')
                   FROM (SELECT p.proname::text || '(' || replace(pg_catalog.oidvectortypes(p.proargtypes), ', ', ',') || ')' AS sig
                           FROM pg_catalog.pg_proc p
                          WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^_?mcp_' AND has_function_privilege('anon', p.oid, 'EXECUTE')) x)
                = ARRAY['mcp_add_todo(text,bytea,text,text,text,text,text,text)',
                 'mcp_authorize_begin(text,text,text,text,text,text,text,text,bytea,bytea)',
                 'mcp_check_access(text,bytea,text)',
                 'mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)',
                 'mcp_find_people(text,bytea,text,text,text,text,text,text,text)',
                 'mcp_get_deal(text,bytea,text,text)',
                 'mcp_get_deal_checklists(text,bytea,text,text,boolean,text)',
                 'mcp_get_status(text,bytea,text)',
                 'mcp_list_all_deals(text,bytea,text,text,text,text,text)',
                 'mcp_list_deals(text,bytea,text,text,text,integer,text)',
                 'mcp_list_todos(text,bytea,text,text,text,text,text,boolean,boolean,text)',
                 'mcp_refresh(text,bytea,text,text,bytea,bytea)',
                 'mcp_register_client(text,text,text,text[],bytea)',
                 'mcp_remove_todo(text,bytea,text,text,text)',
                 'mcp_restore_todo(text,bytea,text,text,text)',
                 'mcp_update_todo(text,bytea,text,text,jsonb,text)',
                 'mcp_write_access(text,bytea,text)']::text[]) INTO v;
  IF (v ->> 'register')::boolean IS NOT TRUE OR (v ->> 'refresh')::boolean IS NOT TRUE OR (v ->> 'prune')::boolean IS NOT TRUE
     OR (v ->> 'children')::boolean IS NOT TRUE OR (v ->> 'cron')::boolean IS NOT TRUE OR (v ->> 'anon_mcp')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'BACKLOG-4263: bounds post-check failed: %', v;
  END IF;
END
$post4263bounds$;
$migq$;
  PERFORM pg_temp.rec('rerun', to_jsonb('ok'::text));
  PERFORM pg_temp.rec('rerun_cron_jobs', to_jsonb((SELECT count(*) FROM cron.job)));
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_temp.rec('rerun', to_jsonb('ERROR ' || SQLSTATE || ' ' || left(SQLERRM, 400)));
END
$rerun$;
-- ================================================================ controls
DO $ctl$
DECLARE c text;
BEGIN
  FOREACH c IN ARRAY ARRAY['c_reg_day', 'c_reg_hour', 'c_reg_global', 'c_reg_secret', 'c_refresh', 'c_prune_rule', 'c_prune_cap', 'c_prune_recheck', 'c_prune_other_child', 'c_prune_grants', 'c_children', 'c_cron', 'c_catalog', 'c_mig_post'] LOOP
    PERFORM pg_temp.rec('CTL_' || c, to_jsonb(pg_temp.iso(c)));
  END LOOP;
  PERFORM pg_temp.rec('t_after_controls', to_jsonb(clock_timestamp()));
  PERFORM pg_temp.rec('CTL_c_equal', to_jsonb(pg_temp.with_old('c_equal')));
  PERFORM pg_temp.rec('REPORT_answers', pg_temp.j(pg_temp.iso('eq_report')));
  PERFORM pg_temp.rec('old_copies_gone', to_jsonb(to_regprocedure('public.mcp_register_client_x4263old(text,text,text,text[],bytea)') IS NULL
                                                   AND to_regprocedure('public.mcp_refresh_x4263old(text,bytea,text,text,bytea,bytea)') IS NULL));
  PERFORM pg_temp.rec('t_after_equal', to_jsonb(clock_timestamp()));
END
$ctl$;
-- ================================================================ mutations
DO $m_M01_reg_day_removed$
DECLARE v text; ok boolean;
BEGIN
  BEGIN
    EXECUTE $mutq$CREATE OR REPLACE FUNCTION public.mcp_register_client(p_secret text, p_client_id text, p_client_name text, p_redirect_uris text[], p_ip_sha256 bytea)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_b text;
BEGIN
  /*BODY:4263-10.4-register*/
  IF public._mcp_secret_ok(p_secret) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_client_metadata');
  END IF;
  IF (SELECT s.enabled FROM public.mcp_settings s WHERE s.id) IS NOT TRUE THEN
    RETURN public._mcp_refuse('busy');
  END IF;
  IF (octet_length(p_ip_sha256) = 32) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_client_metadata');
  END IF;
  IF (p_client_id ~ '^kpr_c_[A-Za-z0-9_-]{22}$'
      AND char_length(p_client_name) BETWEEN 1 AND 100) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_client_metadata');
  END IF;
  IF (cardinality(p_redirect_uris) BETWEEN 1 AND 3
      AND array_position(p_redirect_uris, NULL) IS NULL
      AND NOT EXISTS (SELECT 1 FROM unnest(p_redirect_uris) u(uri)
                       WHERE NOT EXISTS (SELECT 1 FROM public.mcp_redirect_allowlist a WHERE a.redirect_uri = u.uri))) IS NOT TRUE THEN
    RETURN public._mcp_refuse('invalid_redirect_uri');
  END IF;
  v_b := public._mcp_bump('reg_ip:' || encode(p_ip_sha256, 'hex'), interval '1 hour', 60);
  IF v_b IS NOT DISTINCT FROM 'ok' THEN
    v_b := public._mcp_bump('reg_all', interval '1 day', 5000);   /*BOUND:reg_all*/
  END IF;
  IF v_b IS DISTINCT FROM 'ok' THEN
    RETURN public._mcp_refuse(coalesce(v_b, 'busy'));
  END IF;
  INSERT INTO public.mcp_oauth_clients (client_id, client_name, redirect_uris, ip_sha256)
  VALUES (p_client_id, p_client_name, p_redirect_uris, p_ip_sha256)
  ON CONFLICT (client_id) DO NOTHING;
  IF NOT FOUND THEN
    RETURN public._mcp_refuse('invalid_client_metadata');
  END IF;
  RETURN jsonb_build_object('ok', true, 'client_id', p_client_id, 'client_name', p_client_name,
                            'redirect_uris', to_jsonb(p_redirect_uris));
END
$fn$;$mutq$;
    ok := (SELECT md5(p.prosrc) = '262077b5c43fd0db6084d11d0374cbb5' FROM pg_proc p WHERE p.oid = to_regprocedure('public.mcp_register_client(text,text,text,text[],bytea)'));
    v := pg_temp.iso('c_reg_day');
    RAISE EXCEPTION USING ERRCODE = 'MX002';
  EXCEPTION WHEN SQLSTATE 'MX002' THEN NULL;
    WHEN OTHERS THEN v := 'MUTANT ERROR ' || SQLSTATE || ' ' || left(SQLERRM, 300); ok := false;
  END;
  PERFORM pg_temp.rec('MUT_M01_reg_day_removed', jsonb_build_object('applied', ok, 'control', 'c_reg_day', 'expect_red', true, 'red', left(v, 4) IS DISTINCT FROM 'PASS', 'result', left(v, 400)));
END
