  SELECT md5(p.prosrc) INTO v_f FROM pg_proc p WHERE p.oid = to_regprocedure('public.mcp_refresh(text,bytea,text,text,bytea,bytea)');
  IF v_r IS DISTINCT FROM 'ac3e98941cd2f5ef50a16d6409438fb4' OR v_f IS DISTINCT FROM '912c6e001271b289c7a8c929492b4ac9' THEN
