CREATE TEMP TABLE pb_rb_fn AS
  SELECT p.oid::regprocedure::text AS sig, md5(p.prosrc) AS src_md5, p.proacl::text AS acl, p.proconfig AS config, p.prosecdef AS secdef,
         p.proowner AS owner, p.provolatile AS vol, p.proisstrict AS strict, p.proleakproof AS leakproof, p.proparallel AS parallel,
         p.procost AS cost, p.prorows AS nrows
    FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace;
CREATE TEMP TABLE pb_rb_rel AS
  SELECT c.relname::text AS rel, c.relkind::text AS kind, c.relacl::text AS acl, c.relrowsecurity AS rls, c.relforcerowsecurity AS frls,
         c.relowner AS owner, (SELECT count(*) FROM pg_policy y WHERE y.polrelid = c.oid) AS npol
    FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace;
CREATE TEMP TABLE pb_rb_cron AS
  SELECT j.jobid, j.jobname, j.schedule, j.command, j.username, j.active, j.database FROM cron.job j;

SET LOCAL lock_timeout = '3s';
DO $unschedbounds$
BEGIN
  PERFORM cron.unschedule(j.jobid) FROM cron.job j WHERE j.jobname = 'mcp-unused-client-prune';
END
